    /**
     * Install an operating system on a VPS.
     *
     * With this method you can install operating systems and preinstalled images on a VPS.
     *
     * A notable feature is the ability to specify if the installation should be unattended using the `base64InstallText` parameter, allowing for automatic deployment of operating systems.
     *
     * Provide an installFlavour to choose whether a operating system should be deployed with a regular installer or a preinstalled cloudinit image. Check the GET operating-systems function to see what flavours are available for you operating system.
     * When choosing `installer` the `base64InstallText` will be interpreted as a preseed or kickstart file, when choosing `cloudinit` it will be interpreted as cloudinit UserData.
     *
     * SSHKeys are optional for a `cloudinit` installation, when no keys are provided a OneTimePassword will be generated and emailed to you.
     *
     * Provide a license to override the default license of a `preinstallable` operating system. As an example, once a cPanel installation is complete, the default cPanel license will allow you to create 5 user accounts. If the cPanel Pro license is provided, the default license is replaced, and after installation you are able to create 30 user accounts.
     *
     * The response contains a `Content-Location` header with the URL of the action that was started, see [Actions](https://api.transip.nl/rest/docs.html#actions) for more information.
     *
     * Warning: This will create an invoice when a non-free operating system or a non-free control panel is chosen.
     *
     * Body ($data):
     * - operatingSystemName (string): The name of the operating system, e.g. `ubuntu-22.04`
     * - hostname (string, optional): Hostname is required for preinstallable web controlpanels
     * - installFlavour (string, optional): Flavour of OS installation `installer`, `preinstallable` or `cloudinit` check GET operating-system to see what flavours of installation your OS supports. E.g. `cloudinit`
     * - username (string, optional): username used for account creating during cloudinit installation (max 32 chars) E.g. `bob`
     * - hashedPassword (string, optional): password used for cloud init installation account. E.g. `$2y$10$kDwnrkGedxn4HtdAPl86D..sdtnW5aLeHzPuJ8UbAWOOiSiBDXYkm`
     * - sshKeys (string): , `ssh-ed25519 AAAAC3NzaC1l...` (array[string], optional) - array of public ssh keys to use for account creating during installation, e.g. `ssh-rsa AAAAB3NzaC1yc2EAAA...`
     * - base64InstallText (string, optional): Base64 encoded preseed / kickstart / cloudinit instructions, when installing unattended. The decoded string may be up to 49152 bytes (48 KiB) long.
     * - licenses (array[string], optional): Licenses you want to add to your `preinstallable` installation flavor, e.g. `cpanel-premier-200`
     * - acronisTenantId (string, optional): Specify your Acronis Tenant Id if you would like to automatically install the Acronis Client on your VPS. E.g. `eede56d2-1dc6-4fbc-aa3e-ed73f0c41554`
     *
     * POST /v6/vps/{vpsIdentifier}/operating-systems
     *
     * @link https://api.transip.nl/rest/docs.html#vps-operatingsystems-post
     *
     * @param  string  $vpsIdentifier  VPS identifier (name or uuid) E.g. `example-vps`
     * @param  array{operatingSystemName: string, hostname?: string, installFlavour?: string, username?: string, hashedPassword?: string, sshKeys: string, base64InstallText?: string, licenses?: list<string>, acronisTenantId?: string}  $data
     * @return array{}
     *
     * @throws TransipException
     */
    public function installOperatingSystem(string $vpsIdentifier, array $data): array
    {
        return $this->transip->post('vps/'.rawurlencode($vpsIdentifier).'/operating-systems', $data);
    }

