    public function getRescueImages(string $vpsIdentifier): array
    {
        return $this->transip->get('vps/'.rawurlencode($vpsIdentifier).'/rescue-images');
    }

    /**
     * Boot Rescue Image for a VPS.
     *
     * Call this method to boot a specified Rescue image for designated VPS. Some rescue images support ssh keys. When this is the case and ssh keys are
     * provided the vps will be booted with the keys loaded. This can be used to gain root ssh access to the machine without manually adding the keys through the console.
     *
     * Body ($data):
     * - name (string): e.g. `rescueImageName`
     * - sshKeys (string): , `ssh-ed25519 AAAAC3NzaC1l...` (array[string], optional) - array of public ssh key's to use for the rescue image, e.g. `ssh-rsa AAAAB3NzaC1yc2EAAA...`
     *
     * PATCH /v6/vps/{vpsIdentifier}/rescue-images
     *
     * @link https://api.transip.nl/rest/docs.html#vps-rescue-images-patch
     *
     * @param  string  $vpsIdentifier  VPS identifier (name or uuid) E.g. `example-vps`
     * @param  array{name: string, sshKeys: string}  $data
     * @return array{}
     *
     * @throws TransipException
     */
    public function bootRescueImage(string $vpsIdentifier, array $data): array
    {
        return $this->transip->patch('vps/'.rawurlencode($vpsIdentifier).'/rescue-images', $data);
    }

    /**
     * Filter Operating Systems on specifications.
     *
     * We offer a number of operating systems and preinstalled images ready to be installed on any VPS. Using this API call, you can get a list of operating systems and preinstalled images available for a given vps package.
     *
     * Commercial operating systems (such as Windows Server editions) and images shipping a commercial control panel contain the ‘price’ attribute, showing the price per month charged on top of the VPS itself.
     *
     * A list with operating systems can also be found [here](https://www.transip.nl/vps/)
     *
     * An example of all parameters together would be `/v6/operating-systems?productName=vps-performance-c8&addons=vps-addon-1-extra-ip-address,vps-addon-100-gb-extra-harddisk`
     *
     * You can find all product and addon names using our `/v6/products` endpoint
     *
     * Query options ($data):
     * - productName (string): Name of the vps product, e.g. `vps-bladevps-x8`
     * - addons (string, optional): Comma separated list of addons, e.g. `vpsAddon-1-extra-cpu-core`
     *
     * GET /v6/operating-systems
     *
     * @link https://api.transip.nl/rest/docs.html#vps-operatingsystems-filter-get
     *
     * @param  array{productName: string, addons?: string}  $data
     * @return array{operatingSystems: list<array{name: string, description?: string, baseName?: string, version?: string, price?: int, installFlavours: string, licenses?: list<array{name: string, description: string, price: int, recurringPrice: int, type: string, minQuantity: int, maxQuantity: int, isDefault: bool}>, isPreinstallableImage?: bool, installFields?: list<string>, isDefault?: bool}>}
     *
     * @throws TransipException
     */
    public function filterOperatingSystems(array $data): array
    {
        return $this->transip->get('operating-systems', $data);
    }
}
